/**
 * Extract Manifest URL - Normalize webhook data structure
 * Handles both webhook body structure (first pass) and direct fields (Wait node resume)
 * FIX: Check top-level first (Wait node), then body (webhook), process ALL items
 * Handle null values properly - construct from orderId if manifestUrl is null
 * FIX: Validate manifestUrl is a proper URL, not an R2 key
 */
const inputs = $input.all();

function extractPoseFromString(s) {
  if (!s) return null;
  const m = String(s).match(/pose[_-]?(\d{1,2})/i);
  return m ? Number(m[1]) : null;
}

function resolvePoseNumber(input) {
  // Prefer explicit fields first (top-level then body)
  let n = input?.poseNumber ?? input?.body?.poseNumber ?? null;
  if (n !== null && n !== undefined) {
    n = Number(n);
    return Number.isFinite(n) && n >= 0 ? n : null;
  }
  // Soft fallback from filenames/paths if upstream forgot to set poseNumber
  const candidates = [
    input?.fileName,
    input?.imageFileName,
    input?.outputFileName,
    input?.r2Path,
    input?.publicUrl,
    input?.originalImageUrl,
    input?.body?.fileName,
    input?.body?.r2Path,
    input?.body?.publicUrl,
    input?.body?.originalImageUrl,
  ];
  for (const c of candidates) {
    const m = extractPoseFromString(c);
    if (m !== null) return m;
  }
  return null;
}

// Helper function to check if a string is a valid URL
function isValidUrl(str) {
  if (!str || typeof str !== 'string') return false;
  return str.startsWith('http://') || str.startsWith('https://');
}

// Helper function to convert R2 key to full URL
function r2KeyToUrl(r2Key, orderId) {
  if (!r2Key || typeof r2Key !== 'string') return null;
  const baseUrl = 'https://admin.littleherolabs.com/api/manifests';
  // If it's already a full path, use it directly
  if (r2Key.startsWith('book-mvp-simple-adventure/')) {
    return `${baseUrl}/${r2Key}`;
  }
  // Otherwise construct from orderId
  if (orderId) {
    return `${baseUrl}/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`;
  }
  return null;
}

return inputs.map(item => {
  const input = item.json || {};

  // Priority: top-level first (Wait node resume), then body (webhook first pass)
  let manifestUrl = (input.manifestUrl && input.manifestUrl !== '') ? input.manifestUrl : null;
  if (!manifestUrl) {
    manifestUrl = (input.originalManifestUrl && input.originalManifestUrl !== '') ? input.originalManifestUrl : null;
  }

  let orderId = (input.orderId && input.orderId !== '') ? input.orderId : null;
  if (!orderId) {
    orderId = (input.amazonOrderId && input.amazonOrderId !== '') ? input.amazonOrderId : null;
  }

  // Fallback: Extract orderId from manifestKey if available (S3 node might have stripped orderId)
  if ((!orderId || orderId === '') && input.manifestKey) {
    const manifestKeyStr = String(input.manifestKey).trim();
    if (manifestKeyStr && manifestKeyStr !== 'null' && manifestKeyStr !== 'undefined') {
      const patterns = [
        /\/orders\/([^/]+)\//,  // /orders/TEST-ORDER-006/
        /orders\/([^/]+)\//,    // orders/TEST-ORDER-006/
      ];
      for (const pattern of patterns) {
        const keyMatch = manifestKeyStr.match(pattern);
        if (keyMatch && keyMatch[1]) {
          orderId = keyMatch[1];
          console.log(`✓ Extracted orderId from manifestKey: ${orderId} (pattern matched)`);
          break;
        }
      }
      if (!orderId) {
        console.warn(`⚠️ Could not extract orderId from manifestKey: ${manifestKeyStr.substring(0, 100)}`);
      }
    }
  }

  let webhookUrl = (input.webhookUrl && input.webhookUrl !== '') ? input.webhookUrl : null;

  // If not found at top level, check body (webhook structure)
  if (!manifestUrl && input.body && input.body !== input) {
    manifestUrl = (input.body.manifestUrl && input.body.manifestUrl !== '') ? input.body.manifestUrl : null;
    if (!manifestUrl) {
      manifestUrl = (input.body.originalManifestUrl && input.body.originalManifestUrl !== '') ? input.body.originalManifestUrl : null;
    }
    if (!orderId) {
      orderId = (input.body.orderId && input.body.orderId !== '') ? input.body.orderId : null;
      if (!orderId) {
        orderId = (input.body.amazonOrderId && input.body.amazonOrderId !== '') ? input.body.amazonOrderId : null;
      }
    }
    if (!webhookUrl) {
      webhookUrl = (input.body.webhookUrl && input.body.webhookUrl !== '') ? input.body.webhookUrl : null;
    }
  }

  // CRITICAL FIX: Validate manifestUrl is a proper URL, not an R2 key
  // If manifestUrl exists but is not a valid URL (starts with http:// or https://),
  // treat it as an R2 key and convert it to a full URL
  if (manifestUrl && !isValidUrl(manifestUrl)) {
    console.log(`⚠️ manifestUrl is not a valid URL (looks like R2 key): ${manifestUrl.substring(0, 100)}`);
    const convertedUrl = r2KeyToUrl(manifestUrl, orderId);
    if (convertedUrl) {
      manifestUrl = convertedUrl;
      manifestUrl = `${manifestUrl}?v=${Date.now()}`;
      console.log(`✓ Converted R2 key to full URL: ${manifestUrl}`);
    } else {
      console.warn(`⚠️ Could not convert R2 key to URL, will construct from orderId`);
      manifestUrl = null; // Force reconstruction from orderId
    }
  }

  // If no manifestUrl but we have orderId, construct it
  if ((!manifestUrl || manifestUrl === '') && orderId && orderId !== '') {
    const baseUrl = 'https://admin.littleherolabs.com/api/manifests';
    manifestUrl = `${baseUrl}/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`;
    // Add cache-busting parameter to ensure fresh manifest (fixes stale manifest after replacements)
    manifestUrl = `${manifestUrl}?v=${Date.now()}`;
    console.log(`✓ Constructed manifestUrl from orderId: ${manifestUrl} (orderId was: ${orderId})`);
  }

  // Final validation
  if (!manifestUrl || manifestUrl === '') {
    const keys = input ? Object.keys(input).join(', ') : 'no input';
    const manifestUrlValue = input.manifestUrl;
    const orderIdValue = orderId;
    const manifestKeyValue = input.manifestKey || 'not present';
    console.error(`❌ Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
    throw new Error(`Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
  }

  // Add cache-busting parameter to ensure fresh manifest (fixes stale manifest after replacements)
  if (manifestUrl && !manifestUrl.includes('?v=')) {
    manifestUrl = `${manifestUrl}${manifestUrl.includes('?') ? '&' : '?'}v=${Date.now()}`;
  }

  // Validate final manifestUrl is a proper URL
  if (!isValidUrl(manifestUrl)) {
    console.error(`❌ Final manifestUrl is not a valid URL: ${manifestUrl}`);
    throw new Error(`Final manifestUrl is not a valid URL: ${manifestUrl}`);
  }

  // First pass vs resume
  let isFirstPass = input.isFirstPass;
  if (isFirstPass === undefined) {
    const hasWebhookUrl = !!(webhookUrl || (input.body && input.body !== input && input.body.webhookUrl));
    isFirstPass = hasWebhookUrl ? true : false; // default false if undetermined
  }

  // ZERO-SAFE pose number preservation
  const poseNumber = resolvePoseNumber(input);
  return {
    json: {
      ...input, // preserve everything coming in
      manifestUrl,
      originalManifestUrl: manifestUrl,
      orderId: orderId || input.orderId || input.amazonOrderId || null,
      webhookUrl: webhookUrl || input.webhookUrl || null,
      isFirstPass,
      statusUrl: input.statusUrl || input.status_url || null,
      status_url: input.status_url || input.statusUrl || null,
      requestId: input.requestId || input.request_id || null,
      request_id: input.request_id || input.requestId || null,
      poseNumber: (poseNumber ?? null), // <-- preserves 0; only null if truly unknown
      characterHash: input.characterHash || null
    }
  };
});

/**
 * Preserve isFirstPass - Merge manifest with preserved metadata
 * HTTP Request node outputs only the downloaded manifest JSON, overwriting input fields.
 * This node retrieves isFirstPass and other critical metadata from Extract Manifest URL
 * and merges them with the manifest before passing to Parse Submissions.
 */
const inputs = $input.all();
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// Retrieve isFirstPass and other metadata from Extract Manifest URL
let preservedMetadata = null;
try {
  // Try current run index first
  const extractItems = $items('Extract Manifest URL', 0, runIx);
  if (extractItems && Array.isArray(extractItems) && extractItems.length > 0) {
    preservedMetadata = extractItems[0]?.json || {};
    console.log(`✓ Retrieved metadata from Extract Manifest URL (runIndex ${runIx})`);
  }
} catch (e) {
  console.warn(`⚠️ Could not retrieve from Extract Manifest URL (runIndex ${runIx}): ${e.message}`);
  // Try previous run index as fallback
  try {
    const extractItems = $items('Extract Manifest URL', 0, runIx - 1);
    if (extractItems && Array.isArray(extractItems) && extractItems.length > 0) {
      preservedMetadata = extractItems[0]?.json || {};
      console.log(`✓ Retrieved metadata from Extract Manifest URL (runIndex ${runIx - 1})`);
    }
  } catch (e2) {
    console.warn(`⚠️ Could not retrieve from Extract Manifest URL (runIndex ${runIx - 1}): ${e2.message}`);
  }
}

// Process each input item (should be 1 item with the manifest)
return inputs.map(item => {
  const manifest = item.json || {};

  // Extract preserved metadata
  const isFirstPass = preservedMetadata?.isFirstPass !== undefined ? preservedMetadata.isFirstPass : true;
  const manifestUrl = preservedMetadata?.manifestUrl || preservedMetadata?.originalManifestUrl || null;
  const orderId = preservedMetadata?.orderId || preservedMetadata?.amazonOrderId || null;
  const webhookUrl = preservedMetadata?.webhookUrl || null;
  const statusUrl = preservedMetadata?.statusUrl || preservedMetadata?.status_url || null;
  const requestId = preservedMetadata?.requestId || preservedMetadata?.request_id || null;

  console.log(`📋 Preserved metadata: isFirstPass=${isFirstPass}, manifestUrl=${manifestUrl ? 'present' : 'null'}, orderId=${orderId || 'null'}`);

  // Merge manifest with preserved metadata
  return {
    json: {
      ...manifest,  // The downloaded manifest JSON
      // Overlay with preserved metadata
      isFirstPass: isFirstPass,
      manifestUrl: manifestUrl,
      originalManifestUrl: manifestUrl,
      orderId: orderId,
      webhookUrl: webhookUrl,
      statusUrl: statusUrl,
      status_url: statusUrl,
      requestId: requestId,
      request_id: requestId
    }
  };
});

/**
 * Parse Submissions - Extract approved poses from 2A manifest
 * Works with manifest-based input and handles retry scenarios
 * ZERO-SAFE for pose 0 and stable routing via isFirstPass.
 */
const input = $input.first().json || {};
const body  = input.body || input;

// Accept either { manifest } wrapper or the manifest itself
let manifest = body.manifest || body;

// Recover manifest from input if needed (e.g., Preserve node attached it)
if (!manifest || !manifest.schema) {
  manifest = input.manifest || null;
  if (!manifest || !manifest.schema) {
    const manifestUrl = input.manifestUrl || body.manifestUrl || null;
    if (manifestUrl) {
      console.warn(`⚠️ Manifest missing; ensure 'Download 2A Manifest' executed before this node. URL: ${manifestUrl}`);
      throw new Error(`Manifest missing. Please run 'Download 2A Manifest' before Parse Submissions. Manifest URL: ${manifestUrl}`);
    }
    throw new Error(`Invalid manifest: missing or invalid. Input keys: ${Object.keys(input || {}).join(', ')}`);
  }
}

if (manifest.schema !== 'lhb.run-manifest@v2.0') {
  throw new Error(`Invalid manifest schema: ${manifest.schema || 'missing'}`);
}

console.log('=== WORKFLOW 2B STARTED ===');
console.log(`Order: ${manifest.order?.orderId || manifest.order?.amazonOrderId || '(unknown)'}`);
console.log(`Character Hash: ${manifest.characterHash}`);
console.log(`Total poses: ${manifest.poses?.total}`);
console.log(`Approved poses: ${manifest.poses?.approved}`);

// webhookUrl from trigger (webhook first pass) or overlay
const webhookUrl = body.webhookUrl || input.webhookUrl || null;
if (!webhookUrl) console.warn('⚠️ No webhookUrl provided in trigger');

// Execution context (preserved by "Preserve isFirstPass")
const isFirstPass = (input.isFirstPass !== undefined) ? input.isFirstPass : true;
console.log(`📋 Execution context: ${isFirstPass ? 'FIRST PASS' : 'RETRY LOOP'}`);

// Only approved poses
const approvedPoses = (manifest.entries || []).filter(e => e?.approved && e?.status === 'approved');
if (!approvedPoses.length) throw new Error('No approved poses found in manifest');

// CRITICAL: In retry loop, NEVER expand to all poses using a single inbound status_url/request_id.
// Wait/resume carries ONE pose's status fields, so processing all poses would broadcast the same job across poses.
const retryPoseNumber = (!isFirstPass) ? (input.poseNumber ?? body.poseNumber ?? null) : null;
const retryPose = (retryPoseNumber !== null && retryPoseNumber !== undefined) ? Number(retryPoseNumber) : null;
const posesToProcess = (!isFirstPass && Number.isFinite(retryPose))
  ? approvedPoses.filter(p => Number(p?.poseNumber) === retryPose)
  : approvedPoses;

// Bria status count (for logging)
const posesWithStatus    = posesToProcess.filter(p => p.briaStatusUrl || p.briaRequestId).length;
const posesWithoutStatus = posesToProcess.length - posesWithStatus;
console.log(`📊 Bria status in manifest: ${posesWithStatus} with status, ${posesWithoutStatus} need submission (processing ${posesToProcess.length} pose(s))`);

return posesToProcess.map(pose => {
  // Prefer pose-specific status info (if present in manifest entry)
  // BUT: if the 2A pose was replaced (replacedAt/replacementCount), we must re-submit to Bria.
  const wasReplaced = !!(pose.replacedAt || (Number(pose.replacementCount || 0) > 0));
  const poseStatusUrl = wasReplaced ? null : (pose.briaStatusUrl || null);
  const poseReqId     = wasReplaced ? null : (pose.briaRequestId || null);

  // In retry loop, inbound status_url/request_id should apply ONLY to the retried pose (and we filtered above).
  const inboundStatusUrl = (!isFirstPass && Number.isFinite(retryPose)) ? (input.status_url || input.statusUrl || null) : null;
  const inboundReqId     = (!isFirstPass && Number.isFinite(retryPose)) ? (input.request_id || input.requestId || null) : null;

  const statusUrl = poseStatusUrl || inboundStatusUrl || null;
  const requestId = poseReqId     || inboundReqId     || null;

  if (poseStatusUrl) {
    console.log(`✓ Pose ${pose.poseNumber}: Already has Bria status (${statusUrl ? 'has statusUrl' : 'no statusUrl'})`);
  } else {
    console.log(`⚠ Pose ${pose.poseNumber}: No Bria status in manifest - will submit to Bria`);
  }

  return {
    json: {
      poseNumber: (pose.poseNumber ?? null),               // ZERO-SAFE
      // CRITICAL: Prefer approvedKey + cache-busted proxy URL so Bria cannot fetch stale bytes after overwrites\n      originalImageUrl: (()=>{const backendUrl='https://admin.littleherolabs.com';const replacedAtMs=pose.replacedAt?Date.parse(pose.replacedAt):NaN;const buster=(Number.isFinite(replacedAtMs)?replacedAtMs:null)??(Number.isFinite(Number(pose.replacementCount))?Number(pose.replacementCount):null)??(manifest.runStamp?Date.parse(manifest.runStamp):null)??Date.now();if(pose.approvedKey)return `${backendUrl}/api/assets/${pose.approvedKey}?v=${buster}`;const u=pose.publicUrl;if(typeof u==='string'&&(u.startsWith('http://')||u.startsWith('https://')))return u.includes('?v=')?u:`${u}${u.includes('?')?'&':'?'}v=${buster}`;return null;})(),
      characterHash: manifest.characterHash || null,
      orderId: manifest.order?.orderId || manifest.order?.amazonOrderId || null,
      // MEMORY FIX: Removed manifest from each item - retrieve from upstream when needed (reduces memory usage)
      manifestUrl: body.manifestUrl || input.manifestUrl || null,
      webhookUrl,
      statusUrl,
      status_url: statusUrl,
      requestId,
      request_id: requestId,
      retryCount: input.retryCount ?? 0,
      maxRetries: input.maxRetries ?? 5,
      isFirstPass
    }
  };
});

/**
 * Parse Bria status responses (one output item per input item)
 * Works with merged items where Bria fields are top-level.
 * Preserves poseNumber and characterHash from your data.
 */

const inputs = $input.all();

const DONE = new Set(['COMPLETED', 'SUCCESS']);
const WORKING = new Set(['IN_PROGRESS', 'PROCESSING', 'PENDING']);

const now = new Date().toISOString();

return inputs.map(item => {
  const j = item.json ?? {};

  // --- Read Bria status/URL from either top-level or nested result ---
  const status =
    j.status ?? j.state ?? j.result?.status ?? 'UNKNOWN';

  const resultUrl =
    j.result?.image_url ??
    j.result_url ??
    j.url ??
    j.output_url ??
    null;

  // --- Request ID: prefer explicit fields, else parse from statusUrl ---
  let requestId = j.requestId ?? j.request_id ?? j.id ?? null;
  if (!requestId && typeof j.statusUrl === 'string') {
    const m = j.statusUrl.match(/\/status\/([^/?#]+)/);
    if (m) requestId = m[1];
  }

  // --- Retry bookkeeping from your item ---
  const currentRetry = Number(j.retryCount ?? 0);
  const maxRetries   = Number(j.maxRetries ?? 5);

  const shouldDownload = DONE.has(status) && !!resultUrl;
  const shouldRetry    = WORKING.has(status) && currentRetry < maxRetries;

  // --- Preserve your poseNumber and characterHash ---
  const poseNumber = j.poseNumber ?? j.currentPoseNumber ?? null;

  // Keep original characterHash unless it is missing/"nohash"
  let characterHash = j.characterHash ?? null;
  if (!characterHash || characterHash === 'nohash') {
    characterHash = j.orderData?.characterHash ?? characterHash;
  }

  return {
    json: {
      ...j,                  // keep everything you already had (orderData, etc.)
      requestId,
      briaStatus: status,
      resultUrl,
      shouldDownload,
      shouldRetry,
      retryCount: shouldRetry ? currentRetry + 1 : currentRetry,
      maxRetries,
      poseNumber,
      characterHash,
      statusCheckedAt: now,
    },
  };
});

/**
 * Prepare for R2 Upload (multi-item, no cross-workflow refs)
 * Output file path:
 *   book-mvp-simple-adventure/order-generated-assets/characters/{hash}/characters_{hash}_pose{XX}_nobg.png
 *
 * Changes:
 * - Never derive poseNumber from array index (prevents pose 0 → 1 relabeling).
 * - Robust poseNumber inference from file names / URLs / binary metadata.
 * - Hash extraction improved from URLs and filenames.
 * - Strong validation + explicit errors instead of silent fallbacks.
 */

const items = $input.all();

const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';

function isBadHash(h) {
  return !h || typeof h !== 'string' || /^(nohash|unknown)$/i.test(h) || h.trim().length < 4;
}

function hashFromUrl(u) {
  if (!u) return null;
  try {
    const p = new URL(u).pathname;
    return p.match(/\/characters\/([^/]+)\//i)?.[1] ?? null;
  } catch {
    return String(u).match(/characters\/([^/]+)\//i)?.[1] ?? null;
  }
}

function hashFromFileName(name) {
  if (!name) return null;
  // characters_<hash>_poseNN_...
  const m = String(name).match(/characters[_-]([a-f0-9]{6,})[_-]pose/i);
  return m ? m[1] : null;
}

function getBinary(item) {
  const bin = item.binary || {};
  if (!Object.keys(bin).length) return { key: null, data: null, name: null };
  const pref = ['data', 'image', 'file'];
  const key = pref.find(k => bin[k]) || Object.keys(bin)[0];
  const data = bin[key] || null;
  const name = (data && (data.fileName || data.file || data.id || data.mimeType)) ? (data.fileName || data.file || null) : null;
  return { key, data, name };
}

function extractPoseFromString(s) {
  if (!s) return null;
  const str = String(s);
  // common forms: pose03.png, pose_03, ..._pose03_..., pose-03
  let m = str.match(/pose[_-]?(\d{1,2})/i);
  if (m) return Number(m[1]);
  // fallback: /poses/pose03.png
  m = str.match(/\/poses\/pose[_-]?(\d{1,2})/i);
  if (m) return Number(m[1]);
  return null;
}

function inferPoseNumber(j, binName) {
  const direct = j.poseNumber ?? j.currentPoseNumber ?? j.pose?.number ?? null;
  if (direct !== null && direct !== undefined) {
    const n = Number(direct);
    return Number.isFinite(n) ? n : null;
  }
  const candidates = [
    j.fileName,
    j.imageFileName,
    j.outputFileName,
    j.imageUrl,
    j.originalImageUrl,
    j.publicUrl,
    j.r2Path,
    binName,
  ];
  for (const c of candidates) {
    const n = extractPoseFromString(c);
    if (n !== null) return n;
  }
  return null;
}

const out = items.map((item, idx) => {
  const j = item.json || {};
  const { key: binKey, data: binaryData, name: binName } = getBinary(item);

  // ---- poseNumber (strict, never from idx) ----
  const poseNumber = inferPoseNumber(j, binName);
  if (poseNumber === null || !Number.isInteger(poseNumber) || poseNumber < 0) {
    console.error('❌ Could not determine poseNumber', { idx, poseFrom: { json: j.poseNumber, current: j.currentPoseNumber, poseObj: j.pose?.number, fileName: j.fileName, binName } });
    throw new Error(`Unable to determine a valid poseNumber for item index=${idx}.`);
  }

  // ---- characterHash (multiple sources + fallbacks) ----
  let candidateHash =
    j.characterHash ??
    j.orderData?.characterHash ??
    hashFromUrl(j.publicUrl || j.r2Path || j.imageUrl || j.originalImageUrl) ??
    hashFromFileName(j.fileName || binName);

  if (isBadHash(candidateHash)) {
    const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

    // Try Parse Status Response
    try {
      const parseStatusItems = $items('Parse Status Response', 0, runIx);
      if (parseStatusItems?.length) {
        // Prefer same poseNumber if present; otherwise same index
        const byPose = parseStatusItems.find(it => (it?.json?.poseNumber ?? null) === poseNumber);
        const pick = (byPose?.json?.characterHash) ? byPose : (idx < parseStatusItems.length ? parseStatusItems[idx] : null);
        if (pick?.json?.characterHash) {
          candidateHash = pick.json.characterHash;
          console.log(`✓ Retrieved characterHash from Parse Status Response (pose ${poseNumber} / item ${idx}): ${candidateHash}`);
        }
      }
    } catch (e) {
      console.warn(`⚠️ Could not retrieve from Parse Status Response: ${e.message}`);
    }

    // Merge
    if (isBadHash(candidateHash)) {
      try {
        const mergeItems = $items('Merge', 0, runIx);
        if (mergeItems?.length) {
          const byPose = mergeItems.find(it => (it?.json?.poseNumber ?? null) === poseNumber);
          const pick = (byPose?.json?.characterHash) ? byPose : (idx < mergeItems.length ? mergeItems[idx] : null);
          if (pick?.json?.characterHash) {
            candidateHash = pick.json.characterHash;
            console.log(`✓ Retrieved characterHash from Merge (pose ${poseNumber} / item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Merge: ${e.message}`);
      }
    }

    // Check Bria Status
    if (isBadHash(candidateHash)) {
      try {
        const checkStatusItems = $items('Check Bria Status', 0, runIx);
        if (checkStatusItems?.length) {
          const byPose = checkStatusItems.find(it => (it?.json?.poseNumber ?? null) === poseNumber);
          const pick = (byPose?.json?.characterHash) ? byPose : (idx < checkStatusItems.length ? checkStatusItems[idx] : null);
          if (pick?.json?.characterHash) {
            candidateHash = pick.json.characterHash;
            console.log(`✓ Retrieved characterHash from Check Bria Status (pose ${poseNumber} / item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Check Bria Status: ${e.message}`);
      }
    }

    // Parse Submissions
    if (isBadHash(candidateHash)) {
      try {
        const parseSubItems = $items('Parse Submissions', 0, runIx);
        if (parseSubItems?.length) {
          const byPose = parseSubItems.find(it => (it?.json?.poseNumber ?? null) === poseNumber);
          const pick = (byPose?.json?.characterHash) ? byPose : (idx < parseSubItems.length ? parseSubItems[idx] : null);
          if (pick?.json?.characterHash) {
            candidateHash = pick.json.characterHash;
            console.log(`✓ Retrieved characterHash from Parse Submissions (pose ${poseNumber} / item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Parse Submissions: ${e.message}`);
      }
    }
  }

  const characterHash = isBadHash(candidateHash) ? null : candidateHash;
  if (!characterHash) {
    throw new Error(`Missing characterHash for pose ${poseNumber} (item ${idx}).`);
  }

  if (!binaryData) {
