/**
 * Drop Heavy Fields - Remove large binary data but preserve all metadata
 * FIX: Process ALL items (not just first) - each pose needs its own output
 */
const inputs = $input.all();

return inputs.map(item => {
  const j = item.json || {};
  // Remove only the heavy fields that aren't needed
  const cleaned = { ...j };
  delete cleaned.extractedImageData;
  delete cleaned.poseBase64;
  delete cleaned.characterBase64;
  delete cleaned.requestBody;
  // IMPORTANT: Preserve manifest, characterHash, orderId, originalImageUrl, webhookUrl, etc.
  return { json: cleaned };
});

/**
 * Build Bria Payload - Use originalImageUrl from manifest
 * FIX: Process ALL items (not just first) - each pose needs its own payload
 * UPDATE: Use backend proxy endpoint for R2 images when passing to Bria API (required for private R2)
 * BETTER: Proxy endpoint is simpler, has CORS, no expiration, works with private buckets
 * FIX: Handle malformed URLs (missing slashes after https:)
 */
const inputs = $input.all();

// Backend API configuration (hardcoded for private n8n instance)
// PRODUCTION URL: https://admin.littleherolabs.com
// PREVIEW URL: https://387cb69b.little-hero-labs-admin.pages.dev (for testing preview branches)
const backendUrl = 'https://admin.littleherolabs.com';

// Helper function to normalize malformed URLs
function normalizeUrl(url) {
  if (!url || typeof url !== 'string') return url;

  // Fix common URL malformations
  // Fix: https:/domain -> https://domain
  url = url.replace(/^https:\/(?!\/)/, 'https://');
  url = url.replace(/^http:\/(?!\/)/, 'http://');

  return url;
}

// Process all items and convert R2 URLs to backend proxy URLs
const results = await Promise.all(inputs.map(async (item) => {
  const j = item.json;

  // PRIORITY: Use originalImageUrl from manifest (set by Parse Submissions)
  // This ensures we use the correct approved image even if there were retries
  let url = j.originalImageUrl || j.fileUrl || j.imageUrl || j.sourceUrl || null;

  // Robust fallback: recover approvedKey from manifest and build a cache-busted proxy URL.
  // Prevents "No usable image URL found" and prevents stale-cache fetches after overwrites.
  if (!url) {
    try {
      const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
      const mf1 = (() => { try { return $items('Download 2A Manifest', 0, runIx)?.[0]?.json || null; } catch { return null; } })();
      const mf2 = (() => { try { return $items('Preserve isFirstPass', 0, runIx)?.[0]?.json || null; } catch { return null; } })();
      const mf = (mf1 && mf1.schema) ? mf1 : ((mf2 && mf2.schema) ? mf2 : null);
      const pn = (j.poseNumber ?? j.currentPoseNumber ?? null);
      const entry = (mf?.entries && pn !== null) ? mf.entries.find(e => Number(e?.poseNumber) === Number(pn)) : null;
      const key = entry?.approvedKey || null;
      if (key) {
        const replacedAtMs = entry?.replacedAt ? Date.parse(entry.replacedAt) : NaN;
        const buster = Number.isFinite(replacedAtMs) ? replacedAtMs : Date.now();
        url = `${backendUrl}/api/assets/${key}?v=${buster}`;
        console.log(`[Pose ${pn}] Recovered approvedKey from manifest → proxy URL (cache-busted)`);
      }
    } catch (e) {
      console.warn('Fallback manifest lookup failed:', e?.message || String(e));
    }
  }

  // If still no direct URL, try constructing from publicR2Url + storageKey (fallback)
  if (!url) {
    const pub = j.publicR2Url || j.orderData?.publicR2Url;
    const key = j.__meta?.storageKey || j.r2Path || j.__meta?.characterPath || null;
    if (pub && key) {
      url = `${String(pub).replace(/\/$/, '')}/${String(key).replace(/^\//, '')}`;
    }
  }

  // Normalize URL to fix malformed URLs (e.g., https:/domain -> https://domain)
  if (url) {
    url = normalizeUrl(url);
  }

  const poseNumber = (j.poseNumber ?? j.currentPoseNumber ?? null);

  // CRITICAL: If URL is an R2 URL (any format), convert to backend proxy endpoint
  // Backend proxy endpoint (/api/assets/...) is public, has CORS, works with private buckets
  // R2 URLs can be in formats:
  // - Public domain: https://pub-92cec53654f84771956bc84dfea65baa.r2.dev/path
  // - Storage domain: https://bucket.accountid.r2.cloudflarestorage.com/path
  // - Signed URL: https://bucket.accountid.r2.cloudflarestorage.com/path?X-Amz-...
  const isR2Url = url && (
    url.includes('.r2.dev') || 
    url.includes('.r2.cloudflarestorage.com') ||
    url.includes('r2.cloudflarestorage.com')
  );

  if (isR2Url) {
    // CRITICAL: Capture original URL before try block to ensure it's available in catch
    const originalUrl = url;

    try {
      // Validate URL is a string before parsing
      if (!originalUrl || typeof originalUrl !== 'string') {
        throw new Error(`Invalid URL type: ${typeof originalUrl}. Expected string.`);
      }

      // Extract storage key from URL - parse manually since URL constructor may not be available
      let storageKey;
      try {
        // Manual URL parsing - extract pathname
        // Format: https://hostname/path/to/file
        // For signed URLs: https://hostname/path/to/file?X-Amz-Expires=...
        // FIX: Handle both https:// and https:/ (malformed)
        const urlMatch = originalUrl.match(/^https?:\/\/[^\/]+(\/.*?)(?:\?|$)/);
        if (!urlMatch) {
          // Try to fix malformed URL and retry
          const normalized = normalizeUrl(originalUrl);
          const retryMatch = normalized.match(/^https?:\/\/[^\/]+(\/.*?)(?:\?|$)/);
          if (!retryMatch) {
            throw new Error(`Invalid URL format: ${originalUrl.substring(0, 100)}...`);
          }
          const pathname = retryMatch[1] || '/';
          storageKey = pathname.replace(/^\//, ''); // Remove leading slash
        } else {
          const pathname = urlMatch[1] || '/';
          storageKey = pathname.replace(/^\//, ''); // Remove leading slash
        }

        if (!storageKey) {
          throw new Error(`No path found in URL: ${originalUrl}`);
        }
      } catch (urlParseError) {
        const urlErrorMsg = urlParseError?.message || String(urlParseError) || 'Unknown URL parsing error';
        throw new Error(`Failed to parse URL: ${urlErrorMsg}. URL: ${originalUrl.substring(0, 100)}...`);
      }

      // Convert to backend proxy URL
      // Backend proxy endpoint: /api/assets/{storageKey}
      // This endpoint is public, has CORS headers, and works with private R2 buckets
      const vMatch = originalUrl.match(/[?&]v=([^&#]+)/); const v = vMatch ? vMatch[1] : Date.now(); url = `${backendUrl}/api/assets/${storageKey}?v=${v}`;

      console.log(`[Pose ${poseNumber || 'unknown'}] Detected R2 URL: ${originalUrl.substring(0, 80)}...`);
      console.log(`[Pose ${poseNumber || 'unknown'}] Converted to proxy URL: ${url.substring(0, 100)}...`);

    } catch (error) {
      // Safely extract error message
      const errorMsg = error?.message || String(error) || 'Unknown error';
      const errorDetails = error?.stack || error?.toString() || 'No additional details';

      console.error(`[Pose ${poseNumber || 'unknown'}] ❌ Error converting R2 URL to proxy: ${errorMsg}`);
      console.error(`   Error details:`, errorDetails);
      console.error(`   Original URL was: ${originalUrl || 'NOT CAPTURED'}`);

      // DO NOT fall back to original URL - this will fail with private buckets
      throw new Error(`Failed to convert R2 URL to backend proxy: ${errorMsg}. Original URL: ${originalUrl || 'NOT CAPTURED'}`);
    }
  } else if (url && !url.includes('http')) {
    // URL might be a relative path - log warning
    console.warn(`[Pose ${poseNumber || 'unknown'}] ⚠️ URL appears to be relative path: ${url}`);
  }

  // Base64 fallback (shouldn't be needed with manifest)
  let b64 = j.extractedImageData || j.poseBase64 || j.characterBase64 || null;
  if (typeof b64 === 'string') {
    const m = b64.match(/^data:(image\/[a-z0-9+.\-]+);base64,(.*)$/i);
    if (m) b64 = m[2];
    b64 = b64.trim();
    if (b64.length < 12) b64 = null;
  }

  if (!url && !b64) {
    throw new Error(`Pose ${poseNumber}: No usable image URL found`);
  }

  // Build Bria payload
  const briaPayload = {
    image: url || b64,
    meta: {
      correlationId: j.correlationId || null,
      pose: poseNumber,
      characterHash: j.characterHash || null,
      source: url ? 'url' : 'base64'
    }
  };

  const urlType = url ? (url.includes('/api/assets/') ? 'backend proxy URL' : (isR2Url ? 'R2 URL (should be converted!)' : 'public URL')) : 'base64 data';
  console.log(`Pose ${poseNumber}: Using ${url ? 'URL' : 'base64'} - ${urlType}`);

  // CRITICAL: If we're sending an R2 URL that's not converted to proxy, this will fail with private buckets
  if (url && isR2Url && !url.includes('/api/assets/')) {
    throw new Error(`Pose ${poseNumber}: R2 URL detected but not converted to backend proxy! URL: ${url.substring(0, 100)}...`);
  }

  return {
    json: {
      ...j,
      briaPayload: briaPayload,
      briaSource: url ? 'url' : 'base64'
    }
  };
}));

return results;

// Collect items (one per bg-removed pose) into a single summary
const items = $input.all();
if (!items.length) return [{ json: { error: 'NO_BG_POSES' }}];

const first = items[0].json || {};
const job_id = first.job_id || first.orderData?.job_id || first.orderData?.amazonOrderId || first.__meta?.job_id || 'unknown_job';
const characterHash = first.characterHash || first.__meta?.characterHash || first.characterSpecs?.hash || 'nohash';
const orderData = first.orderData || {};

const posesBg = items.map((it) => {
  const j = it.json || {};
  const poseNumber = Number(j.currentPoseNumber ?? j.poseNumber);
  const r2Path = j.r2Path || j.__meta?.storageKey || j.fileName || null;
  const publicUrl = j.publicUrl || null;
  return { poseNumber, r2Path, publicUrl, qaFlags: j.qaFlags || [] };
}).filter(p => Number.isFinite(p.poseNumber) && !!p.publicUrl)
  .sort((a,b) => a.poseNumber - b.poseNumber);

const qa = {
  alphaFringePctMax: Math.max(...posesBg.map(p => (p.qa?.alphaFringePct || 0))),
  minDimsOk: items.every(i => (i.json?.width || 0) >= 1024 && (i.json?.height || 0) >= 1024),
};

return [{ json: { job_id, characterHash, orderData, posesBg, qa } }];

/**
 * Build 2B Manifest - Bria results + Transparency QA aggregation (explode-safe)
 * - Aggregates multiple result items per poseNumber (uploads + QA)
 * - Carries transparency QA flags (qa.transparency.pass/issues/confidence, needs_review)
 * - Sets requiresHumanReview if any pose failed Bria OR transparency QA
 */

const resultItems = $input.all(); // [{json, binary}, ...]
if (!resultItems.length) throw new Error('No results to process');

// -------- Retrieve original manifest (same robust fallback as before) --------
let manifest = resultItems[0].json.manifest;
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

function tryGet(name){
  try {
    const arr = $items(name, 0, runIx);
    if (arr?.length) return arr[0].json;
  } catch {}
  return null;
}

if (!manifest || !manifest.schema) {
  const try1 = tryGet('Download 2A Manifest');
  if (try1?.schema === 'lhb.run-manifest@v2.0') manifest = try1;

  if (!manifest?.schema) {
    const try2 = tryGet('Preserve isFirstPass');
    if (try2?.schema) manifest = try2;
  }
  if (!manifest?.schema) {
    const try3 = tryGet('Parse Submissions');
    if (try3?.manifest?.schema) manifest = try3.manifest;
  }
  if (!manifest?.schema) {
    const try4 = tryGet('Store Submission Result');
    if (try4?.manifest?.schema) manifest = try4.manifest;
  }
  if (!manifest?.schema) {
    try {
      $execution.customData = $execution.customData || {};
      if ($execution.customData.manifest?.schema === 'lhb.run-manifest@v2.0') {
        manifest = $execution.customData.manifest;
      }
    } catch {}
  }
  if (!manifest?.schema) {
    try {
      const sd = $getWorkflowStaticData('global');
      if (sd?.lastManifest?.schema === 'lhb.run-manifest@v2.0') {
        manifest = sd.lastManifest;
      }
    } catch {}
  }
}

if (!manifest?.schema) {
  const first = resultItems[0].json || {};
  const orderId = first.orderId || first.amazonOrderId || null;
  const characterHash = first.characterHash || null;
  const manifestUrl = first.manifestUrl || null;

  throw new Error(
    `Original manifest not found. orderId=${orderId||'null'}, characterHash=${characterHash||'null'}, manifestUrl=${manifestUrl||'null'}`
  );
}

// -------- Aggregate results by poseNumber (merge uploads + QA) --------
function n(num){ const v = Number(num); return Number.isNaN(v) ? null : v; }

const byPose = new Map();
/** Prefer "worse" QA status (any fail wins), and "better" upload status (any true wins). */
function mergePose(prev = {}, cur = {}) {
  const out = { ...prev };

  // identity / meta
  out.poseNumber     = n(cur.poseNumber ?? prev.poseNumber);
  out.characterHash  = cur.characterHash || prev.characterHash;
  out.orderId        = cur.orderId || cur.amazonOrderId || prev.orderId;
  out.webhookUrl     = cur.webhookUrl || prev.webhookUrl;

  // upload / bria
  out.briaProcessed  = (cur.briaProcessed ?? prev.briaProcessed) || false;
  out.uploadComplete = (cur.uploadComplete ?? prev.uploadComplete) || false;
  out.r2Path         = cur.r2Path ?? prev.r2Path;
  out.publicUrl      = cur.publicUrl ?? prev.publicUrl;
  out.briaStatus     = cur.briaStatus ?? prev.briaStatus;
  out.requestId      = cur.requestId || cur.request_id || prev.requestId;
  out.statusUrl      = cur.statusUrl  || cur.status_url  || prev.statusUrl;

  // transparency QA (any failing info should stick)
  const curQA   = cur.qa?.transparency;
  const prevQA  = prev.qa?.transparency;

  if (curQA || prevQA) {
    const passPrev = prevQA?.pass;
    const passCur  = curQA?.pass;
    const issues   = [
      ...(Array.isArray(prevQA?.issues) ? prevQA.issues : (prevQA?.issues ? [prevQA.issues] : [])),
      ...(Array.isArray(curQA?.issues)  ? curQA.issues  : (curQA?.issues  ? [curQA.issues]  : [])),
    ];
    const conf = (typeof curQA?.confidence === 'number') ? curQA.confidence
               : (typeof prevQA?.confidence === 'number') ? prevQA.confidence
               : undefined;

    const finalPass = (passPrev === false || passCur === false) ? false
                    : (passPrev === true || passCur === true) ? true
                    : undefined;

    out.qa = out.qa || {};
    out.qa.transparency = {
      pass: finalPass,
      issues,
      ...(conf !== undefined ? { confidence: conf } : {})
    };
  }

  // needs review flags (from explicit flags or QA fail)
  const curNeeds = (cur.needs_review === true) || (cur.needsReview === true) ||
                   (cur.qa?.transparency?.pass === false);
  const prevNeeds = (prev.needs_review === true) || (prev.needsReview === true) ||
                    (prev.qa?.transparency?.pass === false);

  out.needs_review = curNeeds || prevNeeds || false;

  // reason: prefer transparency fail marker if any fail present
  if (out.needs_review) {
    out.reviewReason = cur.reviewReason || prev.reviewReason || 'transparency_fail_or_low_conf';
  }

  return out;
}

for (const it of resultItems) {
  const r = it.json || {};
  const pn = n(r.poseNumber);
  if (pn === null) continue;
  const prev = byPose.get(pn) || {};
  byPose.set(pn, mergePose(prev, r));
}

// -------- Update manifest entries with aggregated results --------
const updatedEntries = manifest.entries.map((entry) => {
  const epn = n(entry.poseNumber);
  const agg = byPose.get(epn);
  if (!agg) return entry;

  const success = agg.briaProcessed && agg.uploadComplete && !!agg.r2Path;

  // base carry-through
  let next = { ...entry };

  // Construct public URL from R2 path if publicUrl is missing
  // Use the public R2 URL from manifest if available
  const publicR2Base = manifest.order?.publicR2Url || 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
  const publicUrl = agg.publicUrl || (agg.r2Path ? `${publicR2Base}/${agg.r2Path}` : null);

  // Bria success path
  if (success) {
    next = {
      ...next,
      bgRemovedKey: agg.r2Path,
      bgRemovedImageUrl: publicUrl,
      briaRequestId: agg.requestId || null,
      briaStatusUrl: agg.statusUrl || null,
      briaStatus: 'completed',
      needsReview: false,
    };
  } else {
    // Bria failed (or incomplete)
    next = {
      ...next,
      briaStatus: agg.briaStatus || 'failed',
      briaRequestId: agg.requestId || null,
      briaStatusUrl: agg.statusUrl || null,
      needsReview: true,
      reviewReason: agg.reviewReason || agg.briaStatus || 'Bria processing failed',
    };
  }

  // Apply transparency QA overlay (wins over success)
  const tr = agg.qa?.transparency;
  const trFailed = (tr?.pass === false) || (agg.needs_review === true);
  if (trFailed) {
    next.needsReview = true;
    next.reviewReason = agg.reviewReason || 'transparency_fail_or_low_conf';
    next.qa = {
      ...(next.qa || {}),
      transparency: {
        pass: tr?.pass === false ? false : (tr?.pass === true ? true : undefined),
        issues: tr?.issues || [],
        confidence: tr?.confidence,
      },
    };
  }

  return next;
});

// -------- Summary / workflow flags --------
// FIX: Only require bgRemovedKey (not bgRemovedImageUrl) since publicUrl may be null
// bgRemovedKey is the definitive indicator that the pose was successfully processed and uploaded
const processedPoses = updatedEntries.filter(e => e.bgRemovedKey && e.briaStatus === 'completed');
const briaFailed     = updatedEntries.filter(e => e.briaStatus === 'failed' || e.briaStatus === 'MAX_RETRIES_EXCEEDED');
const qaFailed       = updatedEntries.filter(e => e.needsReview && (e.reviewReason || '').includes('transparency'));
const anyNeedsReview = updatedEntries.some(e => e.needsReview);

const manifest2B = {
  ...manifest,
  schema: 'lhb.run-manifest@v2.0',
  runStamp: new Date().toISOString(),
  entries: updatedEntries,
  briaProcessing: {
    totalProcessed: manifest.poses?.approved ?? updatedEntries.length,
    succeeded: processedPoses.length,
    failed: briaFailed.length,
    processingTimeMs: null,
    completedAt: new Date().toISOString(),
  },
  workflow: {
    currentStage: '2B-complete',
    nextWorkflow: anyNeedsReview ? null : '3-compile-book',
    requiresHumanReview: anyNeedsReview,
  },
  reviewQueue: updatedEntries
    .filter(e => e.needsReview)
    .map(e => ({
      poseNumber: e.poseNumber,
      reason: e.reviewReason || 'needs_review',
      briaStatus: e.briaStatus || null,
      imageUrl: e.bgRemovedImageUrl || null,
    })),
  poses: {
    ...manifest.poses,
    briaProcessed: processedPoses.length,
    briaFailed: briaFailed.length,
  },
  summary: {
    percentComplete: Math.round((processedPoses.length / (manifest.poses?.total || updatedEntries.length)) * 100),
    readyForBook: !anyNeedsReview && (processedPoses.length === (manifest.poses?.total || updatedEntries.length)),
    needsHumanReview: anyNeedsReview,
  },
  generatedAt: new Date().toISOString(),
};

// Pass along webhookUrl if present anywhere
const webhookUrl =
  resultItems.find(i => i.json?.webhookUrl)?.json?.webhookUrl || null;

return [{
  json: {
    manifest: manifest2B,
    orderId: manifest.order?.orderId || manifest.order?.amazonOrderId,
    characterHash: manifest.characterHash,
    webhookUrl
  }
}];

/**
 * Prepare Manifest Upload - Set R2 key and convert to uploadable format
 */
const data = $input.first().json;

const manifest = data.manifest;
// Extract orderId from manifest (it might be at manifest.order.orderId or manifest.order.amazonOrderId)
const orderId = data.orderId || manifest?.order?.orderId || manifest?.order?.amazonOrderId;

if (!orderId) {
  throw new Error('Cannot determine orderId. Available keys: ' + Object.keys(data).join(', '));
}

// Construct R2 key
const manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/2b-manifest.json`;

console.log(`Uploading manifest to: ${manifestKey} (orderId: ${orderId})`);

// Convert manifest to buffer for upload
const manifestJSON = JSON.stringify(manifest, null, 2);
const buffer = Buffer.from(manifestJSON, 'utf-8');

return [{
  json: {
    ...data,
    orderId: orderId, // Ensure orderId is in output
    manifestKey: manifestKey,
    manifestBucket: 'little-hero-orders'
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: '2b-manifest.json',
      fileExtension: 'json'
    }
  }
}];

/**
 * Call Backend Webhook - Notify backend that 2B is complete
 * FIX: Retrieve manifest from upstream if S3 node stripped it
 * FIX: Handle both order.orderId and order.amazonOrderId
 * IMPROVED: Better error handling and multiple fallback sources
 */
const data = $input.first().json;
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// Get manifest from input or retrieve from upstream (S3 node might strip it)
let manifest = data.manifest;
let manifestKey = data.manifestKey;

// If manifest is missing or invalid, try to retrieve from upstream nodes
if (!manifest || typeof manifest !== 'object' || manifest.schema !== 'lhb.run-manifest@v2.0') {
  console.log('⚠️ Manifest not found in input, retrieving from upstream...');
  console.log(`   Input data keys: ${Object.keys(data || {}).join(', ')}`);
  console.log(`   Input manifest type: ${typeof manifest}, schema: ${manifest?.schema || 'missing'}`);

  // Priority 1: Try Build 2B Manifest node (most reliable source)
  try {
    const buildItems = $items('Build 2B Manifest', 0, runIx);
    if (buildItems && Array.isArray(buildItems) && buildItems.length > 0) {
      const buildItem = buildItems[0]?.json || {};
      if (buildItem.manifest && typeof buildItem.manifest === 'object' && buildItem.manifest.schema === 'lhb.run-manifest@v2.0') {
        manifest = buildItem.manifest;
        manifestKey = manifestKey || buildItem.manifestKey || null;
        console.log('✓ Retrieved manifest from Build 2B Manifest node');
      }
    }
  } catch (e) {
    console.warn(`⚠️ Could not retrieve from Build 2B Manifest: ${e.message}`);
  }

  // Priority 2: Try Prep Manifest Upload if Build 2B Manifest failed
  if (!manifest || typeof manifest !== 'object' || manifest.schema !== 'lhb.run-manifest@v2.0') {
    try {
      const prepItems = $items('Prep Manifest Upload', 0, runIx);
      if (prepItems && Array.isArray(prepItems) && prepItems.length > 0) {
        const prepItem = prepItems[0]?.json || {};
        if (prepItem.manifest && typeof prepItem.manifest === 'object' && prepItem.manifest.schema === 'lhb.run-manifest@v2.0') {
          manifest = prepItem.manifest;
          manifestKey = manifestKey || prepItem.manifestKey || null;
          console.log('✓ Retrieved manifest from Prep Manifest Upload node');
        }
      }
    } catch (e) {
      console.warn(`⚠️ Could not retrieve from Prep Manifest Upload: ${e.message}`);
    }
  }

  // Priority 3: Try Download 2A Manifest (original source)
  if (!manifest || typeof manifest !== 'object' || manifest.schema !== 'lhb.run-manifest@v2.0') {
    try {
      const downloadItems = $items('Download 2A Manifest', 0, runIx);
      if (downloadItems && Array.isArray(downloadItems) && downloadItems.length > 0) {
        const downloadItem = downloadItems[0]?.json || {};
        // Download 2A Manifest outputs the manifest JSON directly (not wrapped in .manifest)
        if (downloadItem.schema === 'lhb.run-manifest@v2.0') {
          manifest = downloadItem;
          console.log('✓ Retrieved manifest from Download 2A Manifest node');
        }
      }
    } catch (e) {
      console.warn(`⚠️ Could not retrieve from Download 2A Manifest: ${e.message}`);
    }
  }
}

// Final validation - ensure manifest is valid
if (!manifest || typeof manifest !== 'object' || manifest.schema !== 'lhb.run-manifest@v2.0') {
  const manifestType = typeof manifest;
  const manifestSchema = manifest?.schema || 'missing';
  const manifestKeys = manifest ? Object.keys(manifest).slice(0, 10).join(', ') : 'none';
  console.error(`❌ Invalid manifest: type=${manifestType}, schema=${manifestSchema}, keys=[${manifestKeys}]`);
  throw new Error(`Manifest not found or invalid. type=${manifestType}, schema=${manifestSchema}. Cannot build webhook payload.`);
}

// Validate manifest has required structure
if (!manifest.order || typeof manifest.order !== 'object') {
  console.error(`❌ Manifest missing order object. Manifest keys: ${Object.keys(manifest).join(', ')}`);
  throw new Error('Manifest.order is missing or invalid. Cannot build webhook payload.');
}

// Construct manifest URL using backend proxy endpoint (works with private R2)
// UPDATE: Use backend proxy instead of direct R2 URL (required for private R2)
// PRODUCTION URL: https://admin.littleherolabs.com
// PREVIEW URL: https://387cb69b.little-hero-labs-admin.pages.dev (for testing preview branches)
const backendUrl = 'https://admin.littleherolabs.com';

// Construct manifestKey if missing
if (!manifestKey && manifest.order) {
  const orderId = manifest.order.orderId || manifest.order.amazonOrderId;
  if (orderId) {
    manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/2b-manifest.json`;
    console.log(`✓ Constructed manifestKey from orderId: ${manifestKey}`);
  }
}

if (!manifestKey) {
  throw new Error('manifestKey not found and cannot be constructed. Cannot build webhook payload.');
}

// Use backend proxy endpoint for manifest URLs (works with both public and private R2)
const manifestUrl = `${backendUrl}/api/manifests/${manifestKey}`;
console.log(`✓ Using backend proxy for manifest URL: ${manifestUrl}`);

// Get orderId - handle both order.orderId and order.amazonOrderId
const orderId = manifest.order.orderId || manifest.order.amazonOrderId || data.orderId || null;

if (!orderId) {
  console.error(`❌ orderId not found. manifest.order keys: ${Object.keys(manifest.order || {}).join(', ')}, data.orderId: ${data.orderId || 'null'}`);
  throw new Error('orderId not found in manifest.order or data. Cannot build webhook payload.');
}

// Build webhook payload with safe property access
const payload = {
  orderId: orderId,
  manifestUrl: manifestUrl,
  characterHash: manifest.characterHash || null,
  posesProcessed: (manifest.briaProcessing && manifest.briaProcessing.totalProcessed) || 0,
  posesSucceeded: (manifest.briaProcessing && manifest.briaProcessing.succeeded) || 0,
  posesFailed: (manifest.briaProcessing && manifest.briaProcessing.failed) || 0,
  needsReview: (manifest.workflow && manifest.workflow.requiresHumanReview) || false,
  completedAt: (manifest.briaProcessing && manifest.briaProcessing.completedAt) || new Date().toISOString()
};

console.log('=== CALLING BACKEND WEBHOOK ===');
console.log(`Order: ${payload.orderId}`);
console.log(`Manifest URL: ${manifestUrl}`);
console.log(`Succeeded: ${payload.posesSucceeded}, Failed: ${payload.posesFailed}`);
console.log(`Needs Review: ${payload.needsReview}`);

return [{
  json: {
    ...payload,
    webhookUrl: data.webhookUrl || manifest.webhookUrl || null  // Pass through for HTTP Request node
  }
}];

/**
 * Explode QA Array → one item per response element
 * Use when the HTTP node returned ONE item whose json is an ARRAY of Gemini responses.
 * Robust to accidental multiple inputs: flattens any arrays found.
 */
const items = $input.all();
const out = [];

for (const it of items) {
  const payload = it.json;
  if (Array.isArray(payload)) {
    for (const r of payload) out.push({ json: r });
  } else {
    out.push({ json: payload });
  }
}

return out;

/**
 * Transparency QA Build Request — dual-image (composite + original) & filesystem-safe
 * Expects:
 *   - composite image under binary.bg  (from Edit Image → Composite base)
 *   - original cutout under binary.data (transparent PNG)
 * Emits:
 *   - json.geminiRequest (ready to POST)
 *   - carries pose/fileName forward for traceability
 *   - drops binaries to keep memory low
 */

const idx = $itemIndex;
const bin = $input.item.binary || {};

// Prefer expected keys; fall back defensively if needed
const hasComposite = !!bin.bg;
const hasOriginal  = !!bin.data;
const compositeKey = hasComposite ? 'bg'   : Object.keys(bin)[0];
const originalKey  = hasOriginal  ? 'data' : Object.keys(bin)[1] || Object.keys(bin)[0];

if (!compositeKey || !originalKey || !bin[compositeKey] || !bin[originalKey]) {
  throw new Error('Expected binary.bg (composite) and binary.data (original) to be present.');
}

const mimeComposite = bin[compositeKey].mimeType || 'image/png';
const mimeOriginal  = bin[originalKey].mimeType  || 'image/png';

// In filesystem mode, read buffers from disk
const compBuf = await this.helpers.getBinaryDataBuffer(idx, compositeKey); // composite over neon bg
const origBuf = await this.helpers.getBinaryDataBuffer(idx, originalKey);  // original transparent PNG

const compB64 = compBuf.toString('base64');
const origB64 = origBuf.toString('base64');

// Carry identifiers forward
const pose = $json.poseNN ?? $json.poseNumber ?? $json.currentPoseNumber ?? null;
const fileName = $json.generatedFileName ?? $json.storageKey ?? $json.versionedKey ?? $json.fileName ?? null;

const qaPrompt = `
Task: QA for accidental transparency holes *inside* the subject silhouette.

You are given two images:
1) A composite image of the subject over a solid neon green background (#39FF14, RGB 57,255,20).
2) The original PNG with a transparent background (has alpha channel).

Rules (be strict):
- If ANY of the neon background color (#42f10c, ±5% tolerance) is visible *inside* the subject silhouette
  (especially eyes/teeth/mouth/clothing/body), set "needs_review": true.
- Use the original PNG's alpha to determine the silhouette. Any fully transparent area *not connected to the outer
  transparent border* is an interior hole and must be flagged.
- Ignore the outer green area around the figure and a 1–3 px antialias halo at the silhouette edge.
- Sandwich bite marks are frequently mislabeled as a transparency fail, so be careful examining that image.
- If uncertain, set "needs_review": true.
- Be EXTRA careful when reviewing whites of the eyes and teeth.

Return strict JSON only (no markdown):
{"needs_review": true|false, "issues": ["..."], "confidence": 0..1}
`.trim();

const geminiRequest = {
  contents: [{
    role: "user",
    parts: [
      { text: qaPrompt },
      { inline_data: { mime_type: mimeComposite, data: compB64 } },
      { inline_data: { mime_type: mimeOriginal,  data: origB64 } }
    ]
  }],
  generationConfig: {
    response_mime_type: "application/json",
    temperature: 0,
    topP: 0
  }
};

return {
  json: {
    ...$json,
    pose,
    fileName,
    qa: { ...( $json.qa || {} ), transparency: { requested: true, bgHex: "#39FF14" } },
    geminiRequest,
    qaPrompt
  },
  binary: {}
};

// Emits where to fetch the neon canvas from, and what to name its binary
return [{
  json: {
    bgBucket: 'little-hero-assets',
    bgKey: 'book-mvp-simple-adventure/backgrounds/transparency-qa/neon-background.png',
    bgBinary: 'bg' // the binary property name the S3 node should write to
  }
}];

console.log('MANIFEST PRE', {
  currentRunId: $execution.customData?.currentRunId,
  buckets: Object.fromEntries(Object.entries($execution.customData?.poseResults || {}).map(([k,v])=>[k,(v||[]).length])),
});


const j = $json || {};

// Mark as failed
j.qaPass = false;
j.success = false;
j.qa = j.qa || {};
j.qa.combined = { pass: false };

// Track for backend
j.needsReview = true;
j.reviewReason = 'transparency_fail';
j.route = 'manual_review';

// Ensure retryAttempt shows exhausted (at least 3)
j.retryAttempt = Math.max(j.retryAttempt || 0, j.retry?.attempt || 0, 3);

return { json: j, binary: {} };

/**
 * Parse Transparency QA Results — BATCH (explode method)
 * Mode: Run once for all items
 *
 * Input: an ARRAY of merged items (each already contains both:
 *   - original per-image fields (poseNumber, fileName, etc.)
 *   - Gemini response fields (candidates, usageMetadata, modelVersion, responseId)
 *
 * Output: same number of items, each annotated with:
 *   - qa.transparency { pass, issues, confidence }
 *   - needs_review (recall-biased)
 *   - reviewReason (if flagged)
 */

function extractText(resp) {
  try {
    const parts = resp?.candidates?.[0]?.content?.parts || [];
    return parts.map(p => (p && typeof p.text === 'string' ? p.text : '')).join('\n').trim();
  } catch {
    return '';
  }
}

const inputItems = $input.all();
const out = [];

for (const it of inputItems) {
  const merged = it.json || {};
  const resp = {
    candidates: merged.candidates,
    usageMetadata: merged.usageMetadata,
    modelVersion: merged.modelVersion,
    responseId: merged.responseId,
  };

  const raw = extractText(resp);

  let parsed = null;
  try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }

  const needsReviewModel = parsed?.needs_review === true;
  const confidence = Number.isFinite(parsed?.confidence) ? parsed.confidence : null;

  // Recall-biased: flag if parse failed or confidence < 0.99
  const needs_review = needsReviewModel || !parsed || (confidence !== null && confidence < 0.99);

  const issues = Array.isArray(parsed?.issues)
    ? parsed.issues
    : (raw ? [raw] : (needs_review ? ['Uncertain — manual check required'] : []));

  const annotated = {
    ...merged,
    qa: {
      ...(merged.qa || {}),
      transparency: {
        pass: !needs_review,
        issues,
        confidence,
      },
    },
    needs_review,
    reviewReason: needs_review ? 'transparency_fail_or_low_conf' : undefined,
  };

  // Trim heavy response fields (optional)
  delete annotated.candidates;
  delete annotated.usageMetadata;
  delete annotated.modelVersion;
  delete annotated.responseId;

  out.push({ json: annotated, binary: {} });
}

return out;

/**
 * Drop Binary (explode-safe)
 * Input : N items
 * Output: N items (same JSON, binaries cleared)
 */
const items = $input.all();
return items.map(({ json }) => ({ json, binary: {} }));

